import{_ as l,a0 as r,w as s,s as a,ao as u,I as e,x as t,a1 as p,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何用wifi-linux检测AP信号强度 | LCTT x X-CMD","titleTemplate":false,"description":"如何用wifi-linux检测AP信号强度 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用wifi-linux检测AP信号强度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用wifi-linux检测AP信号强度 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150128 How To Monitor Access Point Signal Strength With wifi-linux","title":"如何用wifi-linux检测AP信号强度","tag":"201503","desc":""},"relativePath":"201503/20150128 How To Monitor Access Point Signal Strength With wifi-linux.md","filePath":"[post].md"}'),d={name:"201503/20150128 How To Monitor Access Point Signal Strength With wifi-linux.md"};function f(g,i,x,w,h,m){const n=r("Link");return s(),a("div",null,[i[13]||(i[13]=u(`<h1 id="如何用wifi-linux检测ap信号强度" tabindex="-1">如何用wifi-linux检测AP信号强度 <a class="header-anchor" href="#如何用wifi-linux检测ap信号强度" aria-label="Permalink to “如何用wifi-linux检测AP信号强度”">​</a></h1><p>作为一名python极客，我喜欢在github上挖掘新的用于linux用户的python工具。今天我发现了一款用python写成的用于检测AP信号强度的工具：wifi-linux。</p><p>我已经在<strong>wifi-linux</strong>上实验了大约两个小时，并且它工作的很好但是我希望在不久的将来在作者那里看到一些单元测试，因为命令<strong>plot</strong>无法在我的电脑上工作，并且会导致一些问题。</p><h3 id="什么是wifi-linux" tabindex="-1">什么是wifi-linux <a class="header-anchor" href="#什么是wifi-linux" aria-label="Permalink to “什么是wifi-linux”">​</a></h3><p>根据github上作者账号的官方的 readme.md文件， wifi-linux是一个简单的收集你周围AP的RSSI信息的python脚本，它还会画出RSSI活动图形。</p><p>作者说可以在该程序中可以使用plot命令绘制RSSI 活动图形，但是不幸的是，这对我不可行。wifi-linux也支持其他的命令，比如<strong>bp</strong> 来加入一个断点，<strong>print</strong>会打印一些统计和<strong>启动开关</strong>。</p><p>wifi-linux程序有下面这些依赖：</p><ul><li>dbus-python</li><li>gnuplot-py</li></ul><p>首先我们需要安装所有的包依赖以使它可以运行在我们的linux机器上。</p><h3 id="安装wifi-linux需要的包" tabindex="-1">安装wifi-linux需要的包 <a class="header-anchor" href="#安装wifi-linux需要的包" aria-label="Permalink to “安装wifi-linux需要的包”">​</a></h3><p>我尝试使用python包管理工具pip安装python-dbus但是失败了，因为pip会查找setup.py，但是python-dbus中没有。因此下面的命令不工作。</p><pre><code>pip install dbus-python
</code></pre><p>你可以试一下但是很有可能会在终端中出现下面的错误。</p><pre><code>IOError: [Errno 2] No such file or directory: &#39;/tmp/pip_build_oltjano/dbus-python/setup.py&#39;
</code></pre><p>我该怎么解决这个问题呢？很简单，用下面命令中的系统包管理工具来安装Python DBUS。</p><pre><code>sudo apt-get install python-dbus
</code></pre><p>上面的命令只有在有apt-get包管理器的机器中才可以使用，比如Debian和Ubuntu。</p><p>我们要安装的第二个依赖是gnuplot-py。下载并用tar解压，接着运行setup.py来安装包。</p><p>第一步是下载gnuplot-py。</p><pre><code>wget http://prdownloads.sourceforge.net/gnuplot-py/gnuplot-py-1.8.tar.gz
</code></pre><p>接着使用tar工具解压。</p><pre><code>tar xvf gnuplot-py-1.8.tar.gz
</code></pre><p>接着使用cd命令改变目录。</p><pre><code>cd gnuplot-py-1.8
</code></pre><p>接着运行下面的命令在你的系统中安装gnuplot-py。</p><pre><code>sudo setup.py install
</code></pre><p>安装完成后，你就可以在你的系统中运行wifi-linux了。只需下载并用下面的命令运行脚本。</p><p>用下面的命令下载wifi-linux到你的机器中。</p><pre><code>wget https://github.com/dixel/wifi-linux/archive/master.zip
</code></pre><p>解压master.zip接着使用下面的命令运行list_rsssi.py脚本。</p><pre><code>python list_rssi.py
</code></pre><p>下面的截图说明wifi-linux在工作了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/wifi-linux.png" alt="wifi-linux to monitor wifi signal strength"></p><p>命令<strong>bp</strong>用于像下面那样添加一个断点。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/wifi-linux2.png" alt="the bp command in wifi-linux"></p><p>命令<strong>print</strong>可以用于在终端上显示你机器的状态。下面就是一个例子。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/wifi-linux3.png" alt="the print command"></p><hr>`,38)),e("p",null,[i[1]||(i[1]=t("via: ",-1)),p(n,{href:"http://linoxide.com/linux-how-to/monitor-access-point-signal-strength-wifi-linux/"},{default:o(()=>[...i[0]||(i[0]=[t("http://linoxide.com/linux-how-to/monitor-access-point-signal-strength-wifi-linux/",-1)])]),_:1})]),e("p",null,[i[5]||(i[5]=t("作者：",-1)),p(n,{href:"http://linoxide.com/author/oltjano/"},{default:o(()=>[...i[2]||(i[2]=[t("Oltjano Terpollari",-1)])]),_:1}),i[6]||(i[6]=t(" 译者：",-1)),p(n,{href:"https://github.com/geekpi"},{default:o(()=>[...i[3]||(i[3]=[t("geekpi",-1)])]),_:1}),i[7]||(i[7]=t(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...i[4]||(i[4]=[t("wxy",-1)])]),_:1})]),e("p",null,[i[10]||(i[10]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[8]||(i[8]=[t("LCTT",-1)])]),_:1}),i[11]||(i[11]=t(" 原创翻译，",-1)),p(n,{href:"http://linux.cn/"},{default:o(()=>[...i[9]||(i[9]=[t("Linux中国",-1)])]),_:1}),i[12]||(i[12]=t(" 荣誉推出",-1))])])}const b=l(d,[["render",f]]);export{T as __pageData,b as default};
